"""Freeze exact original panel prompts and reference manifests before generation."""
from pathlib import Path
import json,hashlib
P=Path(__file__).resolve().parent
plan=json.loads((P/'plan.json').read_text());layouts=json.loads((P/'boards/layouts.json').read_text())
manifest=json.loads((P/'refs/manifest.json').read_text())
for i in range(1,15):
 id=f'board-P{i:02}';path=f'boards/png/P{i:02}.png'
 if not any(r['id']==id for r in manifest['references']):manifest['references'].append({'id':id,'path':path,'sha256':hashlib.sha256((P/path).read_bytes()).hexdigest(),'original':True,'rights_status':'original-created-for-pilot','commercial_clearance':None,'acceptance':'draft-layout-expectation'})
(P/'refs/manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
base='''Use case: illustration-story. Create ONE finished original color-webtoon panel, with no text, lettering, symbols resembling writing, captions, sound-effect words, labels, watermark, page border or speech balloons. References in order: (1) the exact original storyboard diagram for this panel, (2) Nera original character sheet, (3) Odo original character sheet, (4) original gallery/props/sentinel sheet. The first image controls the panel composition, actors, spatial axis and event; replace its schematic figures with confident expressive adult drawing. Other sheets control identity and materials, never add their extra turnaround figures or objects. Remove pale outlined placeholder rectangles from the board, preserving quiet background negative space there for separately editable lettering. Do not copy dashed arrows literally; translate trajectory into economical speed accents, posture and force. The two leads are fictional adults: Nera31, lean woman with mature long face, short black curls, warm brown skin, pale muted-yellow asymmetrical rain cape, charcoal practical clothing and boots; Odo38, broad man, square mature face, cropped silver hair, tan skin, ultramarine work jacket with cream cuffs. Keep them exactly recognizable from their sheets, no childlike faces. Refine natural hands, weight-bearing poses and motivated expressions; every held object actually touches its holding hand. Sophisticated clean color-comic drawing with tapered charcoal outlines, deliberate two-to-three-value shadows, matte controlled colors and simple coherent silhouettes; no glossy 3D, generic photoreal painting, ornate decoration or excessive texture. Original slate-gray kite-bodied sentinel has exactly THREE articulated legs, one narrow violet gill slit, no face/eyes/wings. Cool pale daylight and blue-gray shallow water; warm human accents, restrained violet threat. Preserve west on screen LEFT and east shutter on RIGHT until exit aftermath, camera stays south of action axis. Gallery sheet shows a partly open door for design only: panel-specific shutter state overrides it. One medicine flask total, amber glass, sealed metal screw cap upright; Nera's sling is empty unless this panel explicitly places the flask there. No extra vial from the reference costume. Staff is plain wood, intact until P12 then persistently broken. No injuries before P12. No named-artist or franchise imitation.\n'''
notes={1:'Only Nera face/upper torso is visible; Odo/flask/staff are offscreen. Her breath trembles but her gaze is resolved toward right-side light. No threat visible.',2:'Exactly two adults, Odo LEFT and Nera RIGHT, facing each other with eye contact. One upright flask shared at handoff center; Nera holds intact staff in other hand. Shutter fully closed. Gentle trust, not action.',3:'Both adults small on LEFT half so the wide gallery geography dominates. Odo at WEST release, Nera just right with flask upright in chest sling and staff. EAST shutter fully closed. Absolutely NO sentinel visible; empty overhead recess.',4:'Anatomically coherent close wrist insert: Nera forearm/blank dark wrist unit at lower left, chest-sling flask and intact staff visible only as contextual details at lower right. No floating isolated prop studies. Upper half quiet for two UI lines. No activation or writing.',5:'Very tall vertical reveal from dark ceiling recess at top to unfolding three-legged sentinel in mid-right and TWO small adults bottom-left. Nera flask in chest sling/staff, Odo by WEST cord. Monster remains airborne/unfolding, not already defeated. Door closed. Top-to-bottom dread.',6:'Exactly two adults. Nera centered-left planted with bent knees, staff lowered toward forefoot path but NOT yet touching. Odo far LEFT physically reaches the WEST release cord. Sentinel stands right before closed shutter. Nera chest flask upright. Waiting tension; no impact.',7:'Exactly two adults: Odo far left at release, Nera lower center-left. Sentinel RIGHT lunges forefoot right-to-left at Nera; water splash under incoming foot. A visible small gap remains BEFORE staff contact. Staff intact, flask fixed upright to chest, shutter closed. Clear coming threat, not victory.',8:'Contact close/medium view: Nera left and sentinel right; Odo is intentionally outside crop. Wooden staff held in both hands visibly meets the sentinel FRONT FOOT at lower center. Staff slightly compressed/bent but INTACT. Bent knees and counterforce show temporary braking. Violet gill alive; two other legs remain attached. Flask upright in chest sling. Upper margin clear for two UI lines added later. No broken staff or defeated monster.',9:'Exactly two adults, Odo far left at cord, Nera center-left still bracing staff against first forefoot. Sentinel pivots around that blocked foot and sweeps a DIFFERENT SIDE LEG toward Odo, passing above/beside Nera. Show both vectors distinctly. Violet gill alive, shutter closed, chest flask with Nera. No extra leg.',10:'Exactly two adults, Odo LEFT and Nera RIGHT; reciprocal eyelines track ONE sealed flask tossed on one visible right-to-left arc, cap up, between her releasing hand and his open catching hand. Odo other hand remains with release cord; Nera other hand holds intact staff. Nera chest sling visibly EMPTY. Sentinel cropped offscreen; shutter closed.',11:'Exactly one airborne Nera body centered above the sweeping side leg, knees folded, holding staff, chest sling EMPTY. Her rising vault arrests at a short cyan air-braking pressure accent and redirects down-right toward the forelimb; imply ONE continuous motion with restrained speed arcs, no duplicate ghost bodies. Odo on lower left holds upright flask in one hand and pulls WEST release free cord with other; cable runs overhead to EAST shutter, which is now high enough to permit a crouching adult passage. He begins moving right while holding the cord. No staff contact yet, no broken staff/injury yet. Upper margin quiet for skill UI.',12:'One exact impact: Nera staff strikes the sentinel FRONT LIMB JOINT at center-right, wood breaks into two pieces at that visible joint, small scrape on her gripping hand. Broken wood, mechanical joint and counterforce must be visible without smoke hiding them. Nera ONE body follows through toward right. Odo in background far RIGHT physically slips through sufficiently raised shutter holding sealed upright flask; long cord in other hand remains continuous back to WEST fairlead. Sentinel alive, exactly three legs. No premature dead creature or intact spare staff.',13:'Aftermath wide: shutter now near horizontal CENTER of composition because camera tracks east, still west LEFT/east RIGHT. Living sentinel entirely LEFT of shutter, violet gill active, ONE extended foreleg visibly PINNED under lowered shutter bottom at floor. BOTH adults are entirely RIGHT/east of shutter. Odo holds upright flask and releases the long cord, which drops slack; Nera scraped hand and short broken staff piece visible, another broken piece on floor. No full intact staff, no corpse, no reopened shutter.',14:'Quiet close two-shot east of door: Nera LEFT, Odo RIGHT. Odo gently supports her scraped hand with one hand, holds sealed upright flask with other. Nera retains short jagged broken staff piece in other hand; empty sling. Same visible small injury, adult relieved but exhausted expressions, shared trust; both glance toward next passage light. No sentinel or action effects. Framing may crop lower legs for expressive faces. Upper right/left negative space for two small dialogue balloons added later.'}
(P/'prompts').mkdir(exist_ok=True)
for p,l in zip(plan['panels'],layouts['panels']):
 n=p['panel'];text=base+f"\nPANEL P{n:02}. Exact canvas aspect ratio390:{p['target_css_height_at390']}; frame all required subjects inside this single panel. Camera: {p['camera']}. Narrative event: {p['beat']}\nCONTINUITY: {p['continuity_contract']}\nDIRECTED VISUAL REQUIREMENTS: {notes[n]}\nExpected board staging (not a final-art observation): "+' '.join(l['deliberate_choices'])+'\nDo not generate any story text. Preserve quiet regions shown in layout for editable typography. Return one cohesive illustrated panel, not a storyboard, contact sheet or multi-panel page.\n'
 path=P/'prompts'/f'P{n:02}-A-primary.txt'
 if path.exists() and path.read_text()!=text:raise SystemExit('Refusing to overwrite a frozen prompt: '+str(path))
 path.write_text(text)
print('14 prompts and17 original reference records frozen')
